export type SymbolName = 'translate' | 'ladybug' | 'wrench' | 'warning' | 'chevron' | 'chevron-narrow' | 'check'

/**
 * Interpreter's symbols, exported from the Figma rather than drawn here.
 *
 * Every one of these is the designer's own path or bitmap, pasted in unaltered.
 * The `viewBox` on a few of them is the region the shape occupied on its source
 * frame rather than a normalised box, which is why some numbers look arbitrary —
 * that is deliberate, and it means nothing was re-drawn to fit an origin.
 *
 * | Symbol | Colour | Where |
 * | --- | --- | --- |
 * | `translate` | black | Every card, and the detail panel's head |
 * | `ladybug` | `#ff6600` | Interpreter questioned this change |
 * | `wrench` | `#0091ff` | Blocked, waiting, or what to do next |
 * | `warning` | `#b57cff` | This change left something wrong |
 * | `chevron` | `#b2b2b2` | Into a card |
 * | `chevron-narrow` | `#4b4b4b` | Between breadcrumb steps |
 * | `check` | white | Inside the panel's blue circle |
 *
 * `translate` keeps its black rather than following `currentColor`: it is the
 * one symbol here that is not a colour-coded meaning, and every frame draws it
 * black on every surface.
 */

