interface SymbolProps {
  name: SymbolName
  /** Sets the box and, through `currentColor`, the colour. */
  className?: string
}

export function Symbol({ name, className }: SymbolProps) {
  const glyph = VECTOR[name]
  if (glyph === undefined) return null
  return (
    <svg viewBox={glyph.viewBox} fill="none" aria-hidden="true" className={className}>
      {glyph.body}
    </svg>
  )
}
